import {
  useQuery,
} from "@tanstack/react-query";

import {
  ForecastFilters,
  ForecastRecord,
  ForecastStatistics,
} from "../types/forecast.types";

import forecastService from "../service/forecast.service";


/**
 * Fetch forecast chart records.
 */
export const useForecastChart = (
  filters?: ForecastFilters
) => {
  return useQuery<ForecastRecord[]>({
    queryKey: [
      "forecast-chart",
      filters,
    ],

    queryFn: () =>
      forecastService.getForecastChart(
        filters as ForecastFilters
      ),

    enabled: Boolean(
      filters?.entityId
    ),
  });
};


/**
 * Fetch forecast result records.
 */
export const useForecastResults = (
  filters?: ForecastFilters
) => {
  return useQuery<ForecastRecord[]>({
    queryKey: [
      "forecast-results",
      filters,
    ],

    queryFn: () =>
      forecastService.getForecastResults(
        filters as ForecastFilters
      ),

    enabled: Boolean(
      filters?.entityId
    ),
  });
};


/**
 * Fetch calculated forecast statistics.
 */
export const useForecastStatistics = (
  filters?: ForecastFilters
) => {
  return useQuery<ForecastStatistics>({
    queryKey: [
      "forecast-statistics",
      filters,
    ],

    queryFn: () =>
      forecastService.getStatistics(
        filters as ForecastFilters
      ),

    enabled: Boolean(
      filters?.entityId
    ),
  });
};
